import {cargoView,cargoResults} from './cargo.js';
import {initialState,newShip,apply,assigned,services} from './model.js';
const $=s=>document.querySelector(s), escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const key='seven-seas-playtest-v1';let state=initialState(),history=[],tab='Ship',section='Hull',person='';let storageAvailable=true;
try{const saved=localStorage.getItem(key);if(saved){const parsed=JSON.parse(saved);if(parsed.version===1&&Array.isArray(parsed.ships)&&parsed.ships.length)state=parsed;}person=localStorage.getItem('seven-seas-name')||'';}catch{storageAvailable=false;}
const ship=()=>state.ships.find(s=>s.id===state.selected)||state.ships[0];
const sails=['Stowed','Half','Full'];const fmt=n=>Number(n).toLocaleString();
function toast(message){$('#toast').textContent=message;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',3500);}
function save(){try{localStorage.setItem(key,JSON.stringify(state));$('#save-status').textContent='Saved on this device · local playtest';}catch{storageAvailable=false;$('#save-status').textContent='Save unavailable · changes in memory only';toast('Browser storage is unavailable. Export a backup before leaving.');}}
function mutate(action,description){try{const next=apply(ship(),action);history.push(structuredClone(state));history=history.slice(-40);state.ships=state.ships.map(s=>s.id===next.id?next:s);state.log.unshift({at:Date.now(),text:`${person||'Player'} · ${next.name}: ${description}`});state.log=state.log.slice(0,80);save();render();toast(description);}catch(e){toast(e.message);}}
function diagram(){const s=ship();const boxes=[['Bridge',215,80,130,45],['Mast',215,140,130,45],['Gun Deck',190,200,180,48],['Powder Dock',215,263,130,45],['Infirmary',145,323,130,45],['Larder',285,323,130,45],['Hold',215,383,130,45],['Anchors',215,443,130,45],['Rudder',215,503,130,40]];
return `<svg viewBox="0 0 560 590" role="group" aria-label="Sea Wren station diagram. Bow at top, stern at bottom."><defs><pattern id="grid" width="28" height="28" patternUnits="userSpaceOnUse"><path d="M28 0H0V28" fill="none" stroke="#29404b" stroke-width=".6"/></pattern></defs><rect width="560" height="590" fill="url(#grid)"/><text x="280" y="29" text-anchor="middle" fill="#92a9b4" font-size="11" letter-spacing="4">BOW</text><path d="M280 42 Q438 93 446 310 L419 498 Q400 555 280 558 Q160 555 141 498 L114 310 Q122 93 280 42Z" fill="#213a42" stroke="#779b9f" stroke-width="2"/><path d="M280 59 Q421 110 429 310 L404 493 Q385 538 280 541 Q175 538 156 493 L131 310 Q139 110 280 59Z" fill="none" stroke="#496971" stroke-width="1" stroke-dasharray="5 5"/><path d="M280 60V540" stroke="#47616a" stroke-dasharray="3 6"/><text x="53" y="285" text-anchor="middle" fill="#92a9b4" font-size="11" transform="rotate(-90 53 285)" letter-spacing="4">PORT</text><text x="507" y="285" text-anchor="middle" fill="#92a9b4" font-size="11" transform="rotate(90 507 285)" letter-spacing="4">STARBOARD</text>${boxes.map(([name,x,y,w,h])=>{const st=s.stations[name],color=st.hp===0?'#ed8d85':st.hp<st.max?'#e5b76c':'#77bea9';return `<g class="station" role="button" tabindex="0" aria-label="${name}, ${st.hp} of ${st.max} HP" data-section="${name}"><rect x="${x}" y="${y}" width="${w}" height="${h}" rx="5" fill="${section===name?'#3b4e4f':'#173039'}" stroke="${section===name?'#e5b76c':color}"/><text x="${x+w/2}" y="${y+19}" text-anchor="middle" fill="#e1ebec" font-size="13">${name}</text><text x="${x+w/2}" y="${y+35}" text-anchor="middle" fill="${color}" font-size="11">${st.hp} / ${st.max}${st.hp===0?' · DESTROYED':''}</text></g>`;}).join('')}${s.guns.map((g,i)=>{let x=i<2?127:390,y=203+(i%2)*65,c=g.condition!=='operational'?'#ed8d85':g.loaded?'#e5b76c':'#8096a3';return `<g class="station" role="button" tabindex="0" data-gun="${g.id}" aria-label="${g.name}, ${g.condition}, ${g.loaded?'loaded':'needs reload'}"><rect x="${x}" y="${y}" width="43" height="44" rx="5" fill="#182b35" stroke="${c}"/><path d="M${x+12} ${y+10}h19v9h-19zM${x+16} ${y+19}v8h11v-8" fill="${c}"/><text x="${x+21}" y="${y+39}" text-anchor="middle" fill="${c}" font-size="10">${g.condition!=='operational'?'×':g.loaded?'RDY':'LOAD'}</text></g>`;}).join('')}<text x="280" y="580" text-anchor="middle" fill="#92a9b4" font-size="11" letter-spacing="4">STERN · SCHEMATIC LAYOUT</text></svg>`;}
function shipPanel(){const s=ship(),st=section==='Hull'?{hp:s.hull,max:s.maxHull}:s.stations[section];return `<div class="panel-heading"><h2>Ship controls</h2><button id="expand" aria-label="Expand control panel">↗</button></div><div class="card"><div class="card-head"><h3>Sail state</h3><span class="subtle">${[6,9,12][s.sails]} hexes / turn</span></div><div class="segmented">${sails.map((n,i)=>`<button data-sails="${i}" class="${s.sails===i?'active':''}" aria-pressed="${s.sails===i}">${n}</button>`).join('')}</div><p>Turning costs ${[3,6,9][s.sails]} hexes. Sail changes and movement are adjudicated at the table.</p></div><div class="card"><div class="card-head"><h3>${escape(section)}</h3><strong class="${st.hp===0?'red':st.hp<st.max?'amber':''}">${st.hp} / ${st.max} HP</strong></div><p>${section==='Hull'?'The vessel’s overall integrity.':`${services[section]} · ${st.hp===0?'Service unavailable':'Service operational'}. Contents are unchanged by damage.`}</p><div class="actions"><label>HP amount<input id="hp-amount" type="number" value="1" min="1" max="999" step="1"></label><button id="damage" class="danger">− Damage</button><button id="repair">+ Repair</button></div>${section==='Hull'&&s.hull===0?`<p class="red">Hull breached. Roll d12: a 1 sinks immediately; otherwise record turns remaining. Repairs do not automatically cancel sinking.</p>`:''}${section==='Hull'&&(s.hull===0||s.sinking!==null)?`<div class="actions"><label>Sinking turns<input id="sinking" type="number" min="0" max="12" value="${s.sinking??''}"></label><button id="save-sinking">Set countdown</button></div>`:''}</div><div class="section-list">${['Hull',...Object.keys(s.stations)].map(n=>`<button data-section="${n}" class="${section===n?'active':''}"><span>${n}</span><span>${n==='Hull'?s.hull:s.stations[n].hp}</span></button>`).join('')}</div><details><summary>Local playtest tools</summary><p class="subtle">These tools are unrestricted in this device-only prototype. Shared administrator permissions will be added with Firebase.</p><div class="stack"><label>New vessel name<input id="new-name" maxlength="60" placeholder="Vessel name"></label><button id="new-ship">Add a Large Sloop</button><button id="export">Export fleet backup</button></div></details>`;}
function gunsPanel(){const s=ship();return `<div class="panel-heading"><h2>Armaments</h2><span class="subtle">4 / 9 mounts</span></div><p class="subtle">9lb light long guns · d4 damage · 24 hexes · 3 crew each. Reload takes one uninterrupted turn.</p>${['Port','Starboard'].map(side=>`<h3 style="margin:20px 0 12px">${side} battery</h3>${s.guns.filter(g=>g.side===side).map(g=>`<div class="card" id="${g.id}"><div class="card-head"><h3>${g.name}</h3><span class="${g.condition!=='operational'?'red':g.loaded?'amber':'subtle'}">${g.condition!=='operational'?g.condition:g.loaded?'Ready to fire':'Needs reload'}</span></div><p>${g.loaded?escape(g.loaded)+' loaded':'No round loaded'} · ${g.assigned} / 3 crew assigned</p>${g.assigned<3?'<p class="subtle">Understaffed: confirm crew availability at the table.</p>':''}<div class="actions">${g.loaded?`<button class="primary full" data-fire="${g.id}" ${g.condition!=='operational'||!s.stations['Gun Deck'].hp?'disabled':''}>Fire ${g.name.toLowerCase()}</button>`:`<select aria-label="Ammunition for ${g.name}" id="ammo-${g.id}">${s.inventory.filter(i=>i.category==='Ammunition').map(i=>`<option value="${i.id}" ${i.quantity===0?'disabled':''}>${escape(i.name)} (${i.quantity})</option>`).join('')}</select><button data-reload="${g.id}" ${g.condition!=='operational'?'disabled':''}>Complete reload</button>`}</div><details><summary>Condition & crew</summary><label>Cannon condition<select data-condition="${g.id}">${['operational','disabled','destroyed'].map(n=>`<option ${g.condition===n?'selected':''}>${n}</option>`).join('')}</select></label><div class="actions"><label>Assigned crew<input id="assign-${g.id}" type="number" min="0" max="48" value="${g.assigned}"></label><button data-assign="${g.id}">Assign</button></div></details></div>`).join('')}`).join('')}<p class="subtle">Firing records the shot and empties the cannon. Roll attacks, damage and critical effects at the table.</p>`;}
function crewPanel(){const s=ship();return `<h2>Crew & officers</h2><div class="card"><div class="card-head"><h3>General crew</h3><strong>${s.crew} / 48</strong></div><p>Minimum 5 · ${assigned(s)} assigned · ${s.crew-assigned(s)} available</p>${s.crew<5?'<p class="red">Below minimum crew.</p>':''}<div class="actions"><label>Crew aboard<input type="number" id="crew-count" min="0" max="48" value="${s.crew}"></label><button id="crew-save">Update</button></div></div><details><summary>Station allocations</summary><p class="subtle">Cannon crew are assigned in Guns. Do not count those sailors again here.</p>${Object.entries(s.stations).map(([n,st])=>`<div class="actions"><label>${n}<input type="number" id="assign-${n.replaceAll(' ','-')}" value="${st.assigned}" min="0" max="48"></label><button data-assign="${n}">Assign</button></div>`).join('')}</details><h3 style="margin:20px 0 12px">Officer positions</h3><p class="subtle">PC and NPC officer assignments do not change general crew totals.</p><div class="stack">${Object.entries(s.officers).map(([role,name])=>`<label class="officer">${role}<input data-officer="${role}" value="${escape(name)}" placeholder="Unassigned" maxlength="80"></label>`).join('')}</div>`;}
const cargoFilters={query:'',category:'',stock:'all',sort:'name'};
function cargoPanel(){return cargoView(ship(),state.ships,cargoFilters,escape,history.length>0);}
function refreshCargo(){const results=$('#cargo-results');if(results)results.innerHTML=cargoResults(ship(),state.ships,cargoFilters,escape);}
function render(){const s=ship();$('main').classList.toggle('cargo-mode',tab==='Cargo');$('#vessel').innerHTML=state.ships.map(v=>`<option value="${v.id}" ${s.id===v.id?'selected':''}>${escape(v.name)}</option>`).join('');$('#ship-class').textContent=s.type;$('#ship-name').textContent=s.name;$('#sail-tag').textContent=sails[s.sails]+' sails';$('#profile').textContent=person||'Set your name';$('#diagram').innerHTML=diagram();$('#hull-value').textContent=`${s.hull} / ${s.maxHull}`;$('#hull-progress').max=s.maxHull;$('#hull-progress').value=s.hull;$('#hull-progress').setAttribute('aria-label','Hull integrity');$('#hull-note').textContent=s.sinking!==null?(s.sinking===0?'Sinking countdown complete — resolve with GM.':`Sinking · ${s.sinking} turns remaining`):s.hull===0?'Hull breached · record sinking roll':s.hull<s.maxHull?'Hull damaged. Repairs available in Ship controls.':'Hull intact. Ready for open water.';$('#metrics').innerHTML=`<div><small>GENERAL CREW</small><strong>${s.crew} <span class="subtle">/ 48</span></strong></div><div><small>CANNONS READY</small><strong>${s.stations['Gun Deck'].hp?s.guns.filter(g=>g.loaded&&g.condition==='operational').length:0} <span class="subtle">/ 4</span></strong></div><div><small>SPEED</small><strong>${[6,9,12][s.sails]} <span class="subtle">hexes</span></strong></div>`;$('#tabs').innerHTML=['Ship','Guns','Crew','Cargo'].map(t=>`<button data-tab="${t}" class="${tab===t?'active':''}" aria-pressed="${tab===t}">${t}</button>`).join('');$('#panel').innerHTML=({Ship:shipPanel,Guns:gunsPanel,Crew:crewPanel,Cargo:cargoPanel})[tab]();$('#log').innerHTML=state.log.length?state.log.slice(0,12).map(l=>`<li><time>${new Date(l.at).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}</time><span>${escape(l.text)}</span></li>`).join(''):'<li class="empty">The log is quiet. Your next action will appear here.</li>';$('#undo').disabled=!history.length;if(!storageAvailable)$('#save-status').textContent='Save unavailable · changes in memory only';}
function showSection(name){section=name;tab='Ship';render();if(matchMedia('(max-width:800px)').matches)$('aside').scrollIntoView({behavior:'smooth',block:'start'});}
document.addEventListener('click',e=>{const b=e.target.closest('button,[data-section],[data-gun]');if(!b)return;
if(b.dataset.tab){tab=b.dataset.tab;render();}if(b.dataset.section)showSection(b.dataset.section);if(b.dataset.gun){tab='Guns';render();$('#'+b.dataset.gun)?.scrollIntoView({behavior:'smooth',block:'center'});}if(b.dataset.sails!==undefined)mutate({type:'sails',amount:+b.dataset.sails},`Set ${sails[+b.dataset.sails].toLowerCase()} sails`);
if(b.id==='damage'||b.id==='repair'){const n=Number($('#hp-amount').value);if(!Number.isInteger(n)||n<1)return toast('Enter a positive whole HP amount.');mutate({type:'hp',id:section,amount:n*(b.id==='damage'?-1:1)},`${b.id==='damage'?'Damaged':'Repaired'} ${section} by ${n} HP`);}
if(b.dataset.fire)mutate({type:'fire',id:b.dataset.fire},`Fired ${ship().guns.find(g=>g.id===b.dataset.fire).name}`);
if(b.dataset.reload)mutate({type:'reload',id:b.dataset.reload,ammo:$('#ammo-'+b.dataset.reload).value},`Reloaded ${ship().guns.find(g=>g.id===b.dataset.reload).name}`);
if(b.id==='clear-cargo'){Object.assign(cargoFilters,{query:'',category:'',stock:'all'});render();}
if(b.dataset.removeItem){const item=ship().inventory.find(i=>i.id===b.dataset.removeItem);if(item)mutate({type:'remove-item',id:item.id},`Removed ${item.name} (${item.quantity}) from inventory. Undo is available.`);}
if(b.dataset.item)mutate({type:'inventory',id:b.dataset.item,amount:+b.dataset.delta},`${+b.dataset.delta>0?'Added':'Removed'} ${Math.abs(+b.dataset.delta)} ${ship().inventory.find(i=>i.id===b.dataset.item).name}`);
if(b.dataset.assign)mutate({type:'assign',id:b.dataset.assign,amount:Number($('#assign-'+b.dataset.assign.replaceAll(' ','-')).value)},`Updated crew assignment: ${b.dataset.assign}`);
if(b.id==='crew-save')mutate({type:'crew',amount:Number($('#crew-count').value)},'Updated general crew total');
if(b.id==='save-sinking'){if($('#sinking').value==='')return toast('Enter the sinking countdown.');mutate({type:'sinking',amount:Number($('#sinking').value)},'Updated sinking countdown');}
if(b.id==='hull-select')showSection('Hull');if(b.id==='expand')$('aside').classList.toggle('expanded');
if(b.id==='profile'){$('#display-name').value=person;$('#profile-dialog').showModal();}
if((b.id==='undo'||b.id==='cargo-undo')&&history.length){state=history.pop();save();render();toast('Last action undone on this device.');}
if(b.id==='new-ship'){const name=$('#new-name').value.trim();if(!name)return toast('Enter a vessel name.');history.push(structuredClone(state));const v=newShip(crypto.randomUUID(),name);state.ships.push(v);state.selected=v.id;state.log.unshift({at:Date.now(),text:`${person||'Player'} created ${name} from the playtest Sloop template`});save();render();}
if(b.id==='export'){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='seven-seas-fleet.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
if(b.dataset.transfer){const id=b.dataset.transfer,amount=Number($('#transfer-qty-'+id).value),destination=state.ships.find(v=>v.id===$('#transfer-to-'+id).value),item=ship().inventory.find(i=>i.id===id);if(!Number.isInteger(amount)||amount<1||amount>item.quantity)return toast('Enter an available whole quantity.');history.push(structuredClone(state));item.quantity-=amount;const existing=destination.inventory.find(i=>i.name===item.name&&i.category===item.category);if(existing)existing.quantity+=amount;else destination.inventory.push({...item,id:crypto.randomUUID(),quantity:amount});state.log.unshift({at:Date.now(),text:`${person||'Player'} transferred ${amount} ${item.name} from ${ship().name} to ${destination.name}`});save();render();toast('Cargo transferred.');}
});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('g[data-section],g[data-gun]')){e.preventDefault();e.target.dispatchEvent(new MouseEvent('click',{bubbles:true}));}});
document.addEventListener('input',e=>{if(e.target.id==='cargo-search'){cargoFilters.query=e.target.value;refreshCargo();}});
document.addEventListener('change',e=>{if(['cargo-category','cargo-stock','cargo-sort'].includes(e.target.id)){cargoFilters[e.target.id.slice(6)]=e.target.value;refreshCargo();}if(e.target.id==='vessel'){state.selected=e.target.value;section='Hull';save();render();}if(e.target.dataset.condition)mutate({type:'gun-condition',id:e.target.dataset.condition,value:e.target.value},'Changed cannon condition');if(e.target.dataset.officer)mutate({type:'officer',id:e.target.dataset.officer,value:e.target.value},`Updated ${e.target.dataset.officer} assignment`);});
document.addEventListener('submit',e=>{if(e.target.id==='item-form'){e.preventDefault();mutate({type:'add-item',id:crypto.randomUUID(),name:$('#item-name').value,category:$('#item-category').value,amount:Number($('#item-quantity').value)},`Added ${$('#item-name').value.trim()} to inventory`);}if(e.target.id==='profile-form'&&e.submitter?.value==='save'){person=$('#display-name').value.trim();if(!person){e.preventDefault();return;}try{localStorage.setItem('seven-seas-name',person);}catch{}render();}});
window.addEventListener('storage',e=>{if(e.key===key){try{const next=JSON.parse(e.newValue);if(next?.version===1){state=next;history=[];render();toast('Fleet updated in another tab.');}}catch{}}});render();
